import random
import time
def slow_print(text, delay=0.05):
    for char in text:
        print(char, end='', flush=True)
        time.sleep(delay)
    print()
def slow_print2(text, delay=0.05):
    for char in text:
        print(char, end='', flush=True)
        time.sleep(delay)
    print()
def loop():
    slow_print("Truth or Dare?")
    what=input()
    if what.strip().capitalize()=="Truth":
        truth()
    elif what.strip().capitalize()=="Dare":
        dare()
    else:
        slow_print("Invalid choice. Please choose either Truth or Dare.")
        slow_print("Play again? (y/n)")
        pa=input()
    if pa.strip().capitalize()=="Y":
        loop()
    elif pa.strip().capitalize()=="N":
        slow_print("Thanks for playing!")
        return
    else:
        slow_print("Invalid choice. Please choose either y or n.")
        
def truth():
    tr=random.choice(truths)
    slow_print("Your truth is:")
    slow_print2(tr)
    loop()
def dare():
    ty=random.choice(dares)
    slow_print("Your dare is:")
    slow_print2(ty)
    loop()
